#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"

STAMP="$(date +%Y%m%d_%H%M%S)"
BK=".companyos_backups/stop_path_repair_v27_1_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/runtime_control.py "$BK/"
cp -a companyos/runtime/service_supervisor.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_v27_1_patch.py"
python "$PREFIX/tmp/companyos_v27_1_patch.py"
rm -f "$PREFIX/tmp/companyos_v27_1_patch.py"

echo "" | base64 -d > scripts/companyos_verify_stop_path_v27_1
chmod +x scripts/companyos_verify_stop_path_v27_1

scripts/companyos_verify_stop_path_v27_1 | tee .companyos_runtime/stop_path_repair_v27_1.log

git add companyos/runtime/runtime_control.py scripts/companyos_verify_stop_path_v27_1
git diff --cached --quiet || git commit -m "Repair dedicated supervisor stop path assignment"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "BACKUP=$BK"
echo "COMPANYOS_STOP_PATH_REPAIR_V27_1=PASS"
